INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk1-reading-1', 'hsk1', 0, '我的家', 'Gia đình của tôi', '[{"zh":"我叫王明，今年二十岁。","py":"Wǒ jiào Wáng Míng, jīnnián èrshí suì.","vi":"Tôi tên là Vương Minh, năm nay hai mươi tuổi.","audio":"sent-1.mp3","durSec":3.05},{"zh":"我家在北京。","py":"Wǒ jiā zài Běijīng.","vi":"Nhà tôi ở Bắc Kinh.","audio":"sent-2.mp3","durSec":2.2},{"zh":"我家有五个人：爸爸、妈妈、哥哥、妹妹和我。","py":"Wǒ jiā yǒu wǔ ge rén: bàba, māma, gēge, mèimei hé wǒ.","vi":"Nhà tôi có năm người: bố, mẹ, anh trai, em gái và tôi.","audio":"sent-3.mp3","durSec":4.53},{"zh":"爸爸是老师，他在中学工作。","py":"Bàba shì lǎoshī, tā zài zhōngxué gōngzuò.","vi":"Bố tôi là giáo viên, ông ấy làm việc ở trường trung học.","audio":"sent-4.mp3","durSec":3.65},{"zh":"妈妈是医生，她在医院上班。","py":"Māma shì yīshēng, tā zài yīyuàn shàngbān.","vi":"Mẹ tôi là bác sĩ, bà ấy đi làm ở bệnh viện.","audio":"sent-5.mp3","durSec":3.55},{"zh":"哥哥是大学生，他很爱读书。","py":"Gēge shì dàxuéshēng, tā hěn ài dúshū.","vi":"Anh trai tôi là sinh viên đại học, anh ấy rất thích đọc sách.","audio":"sent-6.mp3","durSec":3.73},{"zh":"妹妹今年六岁，她很好玩儿。","py":"Mèimei jīnnián liù suì, tā hěn hǎowánr.","vi":"Em gái năm nay sáu tuổi, bé rất dễ thương.","audio":"sent-7.mp3","durSec":3.65},{"zh":"妹妹喜欢看电视和玩儿。","py":"Mèimei xǐhuan kàn diànshì hé wánr.","vi":"Em gái thích xem tivi và chơi.","audio":"sent-8.mp3","durSec":3.15},{"zh":"我今年上大学，我学汉语。","py":"Wǒ jīnnián shàng dàxué, wǒ xué Hànyǔ.","vi":"Năm nay tôi vào đại học, tôi học tiếng Hán.","audio":"sent-9.mp3","durSec":3.55},{"zh":"我们学校很大，学生很多。","py":"Wǒmen xuéxiào hěn dà, xuésheng hěn duō.","vi":"Trường của chúng tôi rất lớn, sinh viên rất nhiều.","audio":"sent-10.mp3","durSec":3.42},{"zh":"早上我七点起床。","py":"Zǎoshang wǒ qī diǎn qǐchuáng.","vi":"Sáng tôi bảy giờ dậy.","audio":"sent-11.mp3","durSec":2.7},{"zh":"我和同学一起吃早饭。","py":"Wǒ hé tóngxué yìqǐ chī zǎofàn.","vi":"Tôi và bạn cùng lớp ăn sáng cùng nhau.","audio":"sent-12.mp3","durSec":3.05},{"zh":"上午我们上汉语课，老师很好。","py":"Shàngwǔ wǒmen shàng Hànyǔ kè, lǎoshī hěn hǎo.","vi":"Buổi sáng chúng tôi học tiếng Hán, cô giáo rất tốt.","audio":"sent-13.mp3","durSec":3.98},{"zh":"中午我在学校吃饭。","py":"Zhōngwǔ wǒ zài xuéxiào chīfàn.","vi":"Buổi trưa tôi ăn cơm ở trường.","audio":"sent-14.mp3","durSec":2.83},{"zh":"下午我常去图书馆看书。","py":"Xiàwǔ wǒ cháng qù túshūguǎn kànshū.","vi":"Buổi chiều tôi thường đi thư viện đọc sách.","audio":"sent-15.mp3","durSec":3.33},{"zh":"晚上我在家看电视，也和妹妹玩儿。","py":"Wǎnshang wǒ zài jiā kàn diànshì, yě hé mèimei wánr.","vi":"Buổi tối tôi ở nhà xem tivi, cũng chơi với em gái.","audio":"sent-16.mp3","durSec":4.15},{"zh":"星期天，我和家人一起去看电影。","py":"Xīngqītiān, wǒ hé jiārén yìqǐ qù kàn diànyǐng.","vi":"Chủ nhật, tôi đi xem phim cùng gia đình.","audio":"sent-17.mp3","durSec":4},{"zh":"我们都很高兴。","py":"Wǒmen dōu hěn gāoxìng.","vi":"Chúng tôi đều rất vui.","audio":"sent-18.mp3","durSec":2.3}]', '[{"word":"老师","py":"lǎoshī","vi":"giáo viên"},{"word":"医院","py":"yīyuàn","vi":"bệnh viện"},{"word":"大学","py":"dàxué","vi":"trường đại học"},{"word":"图书馆","py":"túshūguǎn","vi":"thư viện"},{"word":"起床","py":"qǐchuáng","vi":"thức dậy"},{"word":"汉语","py":"Hànyǔ","vi":"tiếng Hán"},{"word":"家人","py":"jiārén","vi":"người thân trong gia đình"}]', '[{"q":"王明的爸爸在哪里工作？","options":["在医院","在中学","在大学"],"answer":1,"qVi":"Bố của Vương Minh làm việc ở đâu?"},{"q":"王明的妹妹今年多大了？","options":["五岁","六岁","七岁"],"answer":1,"qVi":"Em gái Vương Minh năm nay bao nhiêu tuổi?"},{"q":"王明在大学学什么？","options":["英语","汉语","电脑"],"answer":1,"qVi":"Vương Minh học gì ở đại học?"},{"q":"下午王明常去哪里看书？","options":["图书馆","家里","电影院"],"answer":0,"qVi":"Buổi chiều Vương Minh thường đi đâu đọc sách?"},{"q":"王明家有几口人？","options":["四个人","六个人","五个人"],"answer":2,"qVi":"Nhà Vương Minh có mấy người?"}]', 'audio/reading/hsk1-reading-1', 183, 61);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk1-reading-2', 'hsk1', 1, '小明的一天', 'Một ngày của Tiểu Minh', '[{"zh":"小明是一个中学生，今年十五岁。","py":"Xiǎomíng shì yí ge zhōngxuéshēng, jīnnián shíwǔ suì.","vi":"Tiểu Minh là học sinh trung học, năm nay mười lăm tuổi.","audio":"sent-1.mp3","durSec":4.15},{"zh":"早上六点半，他起床了。","py":"Zǎoshang liù diǎn bàn, tā qǐchuáng le.","vi":"Sáu giờ rưỡi sáng, cậu ấy dậy.","audio":"sent-2.mp3","durSec":3.33},{"zh":"他先喝牛奶，再吃鸡蛋和面包。","py":"Tā xiān hē niúnǎi, zài chī jīdàn hé miànbāo.","vi":"Cậu ấy trước uống sữa, sau ăn trứng và bánh mì.","audio":"sent-3.mp3","durSec":3.98},{"zh":"七点半，他坐汽车去学校。","py":"Qī diǎn bàn, tā zuò qìchē qù xuéxiào.","vi":"Bảy giờ rưỡi, cậu ấy đi học bằng ô tô.","audio":"sent-4.mp3","durSec":3.35},{"zh":"他家在学校旁边，不很远。","py":"Tā jiā zài xuéxiào pángbiān, bù hěn yuǎn.","vi":"Nhà cậu ấy ở cạnh trường, không xa lắm.","audio":"sent-5.mp3","durSec":3.45},{"zh":"八点上课，他很认真。","py":"Bā diǎn shàngkè, tā hěn rènzhēn.","vi":"Tám giờ vào học, cậu ấy rất nghiêm túc.","audio":"sent-6.mp3","durSec":2.9},{"zh":"上午他上汉语课和电脑课。","py":"Shàngwǔ tā shàng Hànyǔ kè hé diànnǎo kè.","vi":"Buổi sáng cậu ấy học tiếng Hán và học tin học.","audio":"sent-7.mp3","durSec":3.55},{"zh":"他汉语很好，会说很多话。","py":"Tā Hànyǔ hěn hǎo, huì shuō hěn duō huà.","vi":"Tiếng Hán của cậu ấy rất giỏi, nói được rất nhiều câu.","audio":"sent-8.mp3","durSec":3.48},{"zh":"中午十二点，他和同学在学校吃饭。","py":"Zhōngwǔ shí\u0027èr diǎn, tā hé tóngxué zài xuéxiào chīfàn.","vi":"Mười hai giờ trưa, cậu ấy và bạn cùng lớp ăn cơm ở trường.","audio":"sent-9.mp3","durSec":4.35},{"zh":"下午两点半，他和朋友在学校打球。","py":"Xiàwǔ liǎng diǎn bàn, tā hé péngyou zài xuéxiào dǎ qiú.","vi":"Hai giờ rưỡi chiều, cậu ấy và bạn bè chơi bóng ở trường.","audio":"sent-10.mp3","durSec":4.33},{"zh":"下午四点半，他回家写汉字。","py":"Xiàwǔ sì diǎn bàn, tā huí jiā xiě Hànzì.","vi":"Bốn giờ rưỡi chiều, cậu ấy về nhà viết chữ Hán.","audio":"sent-11.mp3","durSec":3.75},{"zh":"晚上六点，他和爸爸、妈妈一起吃晚饭。","py":"Wǎnshang liù diǎn, tā hé bàba, māma yìqǐ chī wǎnfàn.","vi":"Sáu giờ tối, cậu ấy ăn cơm tối cùng bố mẹ.","audio":"sent-12.mp3","durSec":4.5},{"zh":"晚饭后，他看电视，也看书。","py":"Wǎnfàn hòu, tā kàn diànshì, yě kànshū.","vi":"Sau bữa tối, cậu ấy xem tivi, cũng đọc sách.","audio":"sent-13.mp3","durSec":3.55},{"zh":"九点半，他准备睡觉。","py":"Jiǔ diǎn bàn, tā zhǔnbèi shuìjiào.","vi":"Chín giờ rưỡi, cậu ấy chuẩn bị đi ngủ.","audio":"sent-14.mp3","durSec":2.88},{"zh":"十点，他睡觉了。","py":"Shí diǎn, tā shuìjiào le.","vi":"Mười giờ, cậu ấy đi ngủ rồi.","audio":"sent-15.mp3","durSec":2.45},{"zh":"他觉得这一天很好，也很高兴。","py":"Tā juéde zhè yì tiān hěn hǎo, yě hěn gāoxìng.","vi":"Cậu ấy thấy ngày này rất đẹp, cũng rất vui.","audio":"sent-16.mp3","durSec":3.92},{"zh":"明天他还要早起，去学校学汉语。","py":"Míngtiān tā hái yào zǎo qǐ, qù xuéxiào xué Hànyǔ.","vi":"Mai cậu ấy còn phải dậy sớm, đi học tiếng Hán.","audio":"sent-17.mp3","durSec":4.25}]', '[{"word":"中学生","py":"zhōngxuéshēng","vi":"học sinh trung học"},{"word":"起床","py":"qǐchuáng","vi":"thức dậy"},{"word":"牛奶","py":"niúnǎi","vi":"sữa bò"},{"word":"汽车","py":"qìchē","vi":"ô tô"},{"word":"认真","py":"rènzhēn","vi":"nghiêm túc, chăm chú"},{"word":"准备","py":"zhǔnbèi","vi":"chuẩn bị"},{"word":"睡觉","py":"shuìjiào","vi":"đi ngủ"},{"word":"电脑","py":"diànnǎo","vi":"máy tính"}]', '[{"q":"小明早上几点起床？","options":["七点半","六点半","六点"],"answer":1,"qVi":"Tiểu Minh mấy giờ dậy vào buổi sáng?"},{"q":"他早上先喝什么？","options":["牛奶","茶","水"],"answer":0,"qVi":"Sáng cậu ấy uống gì trước?"},{"q":"他怎么去学校？","options":["走路","坐火车","坐汽车"],"answer":2,"qVi":"Cậu ấy đi học bằng cách nào?"},{"q":"下午他在学校和朋友做什么？","options":["打球","看电影","买东西"],"answer":0,"qVi":"Buổi chiều cậu ấy làm gì với bạn bè ở trường?"},{"q":"他晚上几点睡觉？","options":["九点半","十点","十点半"],"answer":1,"qVi":"Tối cậu ấy mấy giờ đi ngủ?"}]', 'audio/reading/hsk1-reading-2', 186, 62);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk1-reading-3', 'hsk1', 2, '买东西', 'Đi mua sắm', '[{"zh":"星期六，李娜和妈妈去商场买东西。","py":"Xīngqīliù, Lǐ Nà hé māma qù shāngchǎng mǎi dōngxi.","vi":"Thứ bảy, Lý Na và mẹ đi trung tâm thương mại mua đồ.","audio":"sent-1.mp3","durSec":4.17},{"zh":"商场里人很多。","py":"Shāngchǎng li rén hěn duō.","vi":"Trong trung tâm thương mại có rất nhiều người.","audio":"sent-2.mp3","durSec":2.45},{"zh":"李娜想买衣服。","py":"Lǐ Nà xiǎng mǎi yīfu.","vi":"Lý Na muốn mua quần áo.","audio":"sent-3.mp3","durSec":2.48},{"zh":"她看到很多衣服，有大的，也有小的。","py":"Tā kàndào hěn duō yīfu, yǒu dà de, yě yǒu xiǎo de.","vi":"Cô ấy thấy rất nhiều quần áo, có cái to, cũng có cái nhỏ.","audio":"sent-4.mp3","durSec":4.2},{"zh":"她问：\"这个多少钱？\"","py":"Tā wèn: \"Zhège duōshao qián?\"","vi":"Cô ấy hỏi: \"Cái này bao nhiêu tiền?\"","audio":"sent-5.mp3","durSec":2.67},{"zh":"那个人说：\"一百块。\"","py":"Nàge rén shuō: \"Yìbǎi kuài.\"","vi":"Người đó nói: \"Một trăm tệ.\"","audio":"sent-6.mp3","durSec":2.6},{"zh":"李娜觉得太贵了。","py":"Lǐ Nà juéde tài guì le.","vi":"Lý Na thấy quá đắt.","audio":"sent-7.mp3","durSec":2.52},{"zh":"妈妈说：\"我们去那边看看吧。\"","py":"Māma shuō: \"Wǒmen qù nàbiān kànkan ba.\"","vi":"Mẹ nói: \"Chúng ta qua bên kia xem thử đi.\"","audio":"sent-8.mp3","durSec":3.4},{"zh":"那边还有一个商店。","py":"Nàbiān hái yǒu yí ge shāngdiàn.","vi":"Bên kia còn có một cửa hàng.","audio":"sent-9.mp3","durSec":2.65},{"zh":"那里的衣服不贵，也很好看。","py":"Nàlǐ de yīfu bú guì, yě hěn hǎokàn.","vi":"Quần áo ở đó không đắt, cũng rất đẹp.","audio":"sent-10.mp3","durSec":3.58},{"zh":"那边的衣服八十块，不很贵。","py":"Nàbiān de yīfu bāshí kuài, bù hěn guì.","vi":"Quần áo bên đó tám mươi tệ, không đắt lắm.","audio":"sent-11.mp3","durSec":3.6},{"zh":"李娜很高兴，马上穿上了。","py":"Lǐ Nà hěn gāoxìng, mǎshàng chuān shàng le.","vi":"Lý Na rất vui, mặc vào ngay.","audio":"sent-12.mp3","durSec":3.55},{"zh":"妈妈也买了水果和牛奶。","py":"Māma yě mǎi le shuǐguǒ hé niúnǎi.","vi":"Mẹ cũng mua trái cây và sữa.","audio":"sent-13.mp3","durSec":3.35},{"zh":"中午，她们在商场旁边吃饭。","py":"Zhōngwǔ, tāmen zài shāngchǎng pángbiān chīfàn.","vi":"Buổi trưa, các cô ăn cơm cạnh trung tâm thương mại.","audio":"sent-14.mp3","durSec":3.42},{"zh":"她们吃了米饭和鸡蛋。","py":"Tāmen chī le mǐfàn hé jīdàn.","vi":"Các cô ăn cơm và trứng.","audio":"sent-15.mp3","durSec":2.83},{"zh":"吃完饭，妈妈给李娜买了一个书包。","py":"Chī wán fàn, māma gěi Lǐ Nà mǎi le yí ge shūbāo.","vi":"Ăn cơm xong, mẹ mua cho Lý Na một chiếc cặp sách.","audio":"sent-16.mp3","durSec":3.85},{"zh":"李娜说：\"谢谢妈妈！我很喜欢。\"","py":"Lǐ Nà shuō: \"Xièxie māma! Wǒ hěn xǐhuan.\"","vi":"Lý Na nói: \"Cảm ơn mẹ! Con rất thích.\"","audio":"sent-17.mp3","durSec":3.7},{"zh":"下午，她们很高兴，一起回家了。","py":"Xiàwǔ, tāmen hěn gāoxìng, yìqǐ huí jiā le.","vi":"Buổi chiều, các cô rất vui, cùng nhau về nhà.","audio":"sent-18.mp3","durSec":4}]', '[{"word":"商场","py":"shāngchǎng","vi":"trung tâm thương mại"},{"word":"东西","py":"dōngxi","vi":"đồ vật, đồ đạc"},{"word":"贵","py":"guì","vi":"đắt"},{"word":"块","py":"kuài","vi":"tệ (đơn vị tiền Trung Quốc)"},{"word":"水果","py":"shuǐguǒ","vi":"trái cây"},{"word":"书包","py":"shūbāo","vi":"cặp sách"},{"word":"穿上","py":"chuān shàng","vi":"mặc vào"}]', '[{"q":"李娜和谁去买东西？","options":["和爸爸","和同学","和妈妈"],"answer":2,"qVi":"Lý Na đi mua sắm với ai?"},{"q":"第一件衣服多少钱？","options":["一百块","八十块","五十块"],"answer":0,"qVi":"Chiếc quần áo đầu tiên giá bao nhiêu?"},{"q":"李娜为什么不去第一个地方买？","options":["衣服太贵了","衣服不好看","没有衣服了"],"answer":0,"qVi":"Vì sao Lý Na không mua ở nơi đầu tiên?"},{"q":"妈妈还买了什么？","options":["鸡蛋和米饭","水果和牛奶","书包和水"],"answer":1,"qVi":"Mẹ còn mua thêm gì?"},{"q":"吃完饭，妈妈给李娜买了什么？","options":["一个书包","一件衣服","一些水果"],"answer":0,"qVi":"Ăn cơm xong, mẹ mua gì cho Lý Na?"}]', 'audio/reading/hsk1-reading-3', 179, 59);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk2-reading-1', 'hsk2', 0, '第一次坐飞机', 'Lần đầu tiên đi máy bay', '[{"zh":"王小红是北京的大学生。","py":"Wáng Xiǎohóng shì Běijīng de dàxuéshēng.","vi":"Vương Tiểu Hồng là sinh viên đại học ở Bắc Kinh.","audio":"sent-1.mp3","durSec":3.42},{"zh":"今年假期，她要和同学一起去上海旅行。","py":"Jīnnián jiàqī, tā yào hé tóngxué yìqǐ qù Shànghǎi lǚxíng.","vi":"Kỳ nghỉ năm nay, cô ấy sẽ đi du lịch Thượng Hải cùng bạn học.","audio":"sent-2.mp3","durSec":4.7},{"zh":"她们买了两张机票。","py":"Tāmen mǎi le liǎng zhāng jīpiào.","vi":"Các cô mua hai vé máy bay.","audio":"sent-3.mp3","durSec":2.7},{"zh":"这是王小红第一次坐飞机。","py":"Zhè shì Wáng Xiǎohóng dì yí cì zuò fēijī.","vi":"Đây là lần đầu tiên Vương Tiểu Hồng đi máy bay.","audio":"sent-4.mp3","durSec":3.52},{"zh":"早上六点，她来到机场。","py":"Zǎoshang liù diǎn, tā láidào jīchǎng.","vi":"Sáu giờ sáng, cô ấy đến sân bay.","audio":"sent-5.mp3","durSec":3.12},{"zh":"机场里人很多，她们排队取票。","py":"Jīchǎng li rén hěn duō, tāmen páiduì qǔ piào.","vi":"Sân bay rất đông người, các cô xếp hàng lấy vé.","audio":"sent-6.mp3","durSec":3.9},{"zh":"八点半，飞机要起飞了。","py":"Bā diǎn bàn, fēijī yào qǐfēi le.","vi":"Tám giờ rưỡi, máy bay sắp cất cánh.","audio":"sent-7.mp3","durSec":3.05},{"zh":"王小红有点儿高兴，也有点儿怕。","py":"Wáng Xiǎohóng yǒudiǎnr gāoxìng, yě yǒudiǎnr pà.","vi":"Vương Tiểu Hồng hơi vui, nhưng cũng hơi sợ.","audio":"sent-8.mp3","durSec":3.75},{"zh":"同学告诉她：\"别怕，坐飞机很安全。\"","py":"Tóngxué gàosu tā: \"Bié pà, zuò fēijī hěn ānquán.\"","vi":"Bạn học nói với cô ấy: \"Đừng sợ, đi máy bay rất an toàn.\"","audio":"sent-9.mp3","durSec":4.23},{"zh":"她的座位很好，能看到白云。","py":"Tā de zuòwèi hěn hǎo, néng kàndào báiyún.","vi":"Chỗ ngồi của cô ấy rất đẹp, nhìn thấy được mây trắng.","audio":"sent-10.mp3","durSec":3.63},{"zh":"天很蓝，云很白，真好看！","py":"Tiān hěn lán, yún hěn bái, zhēn hǎokàn!","vi":"Trời rất xanh, mây rất trắng, đẹp thật!","audio":"sent-11.mp3","durSec":3.23},{"zh":"两个小时以后，飞机到了上海。","py":"Liǎng ge xiǎoshí yǐhòu, fēijī dàole Shànghǎi.","vi":"Hai tiếng sau, máy bay đến Thượng Hải.","audio":"sent-12.mp3","durSec":3.77},{"zh":"她们先到酒店放东西。","py":"Tāmen xiān dào jiǔdiàn fàng dōngxi.","vi":"Các cô trước đến khách sạn để đồ.","audio":"sent-13.mp3","durSec":3.08},{"zh":"下午，她们去海边玩儿。","py":"Xiàwǔ, tāmen qù hǎibiān wánr.","vi":"Buổi chiều, các cô đi chơi ở biển.","audio":"sent-14.mp3","durSec":2.9},{"zh":"上海非常漂亮，王小红照了很多照片。","py":"Shànghǎi fēicháng piàoliang, Wáng Xiǎohóng zhào le hěn duō zhàopiàn.","vi":"Thượng Hải rất đẹp, Vương Tiểu Hồng chụp rất nhiều ảnh.","audio":"sent-15.mp3","durSec":4.55},{"zh":"她还给妈妈打了电话：\"妈妈，上海真好！\"","py":"Tā hái gěi māma dǎ le diànhuà: \"Māma, Shànghǎi zhēn hǎo!\"","vi":"Cô ấy còn gọi điện cho mẹ: \"Mẹ ơi, Thượng Hải đẹp thật!\"","audio":"sent-16.mp3","durSec":4.47},{"zh":"妈妈说：\"玩得开心点儿。\"","py":"Māma shuō: \"Wán de kāixīn diǎnr.\"","vi":"Mẹ nói: \"Con chơi cho vui nhé.\"","audio":"sent-17.mp3","durSec":3},{"zh":"一个星期以后，她们坐飞机回北京了。","py":"Yí ge xīngqī yǐhòu, tāmen zuò fēijī huí Běijīng le.","vi":"Một tuần sau, các cô đi máy bay về Bắc Kinh.","audio":"sent-18.mp3","durSec":4.38},{"zh":"王小红觉得这次旅行很有意思。","py":"Wáng Xiǎohóng juéde zhè cì lǚxíng hěn yǒuyìsi.","vi":"Vương Tiểu Hồng thấy chuyến đi này rất thú vị.","audio":"sent-19.mp3","durSec":4.03}]', '[{"word":"假期","py":"jiàqī","vi":"kỳ nghỉ, ngày nghỉ"},{"word":"旅行","py":"lǚxíng","vi":"du lịch"},{"word":"机场","py":"jīchǎng","vi":"sân bay"},{"word":"起飞","py":"qǐfēi","vi":"cất cánh"},{"word":"安全","py":"ānquán","vi":"an toàn"},{"word":"座位","py":"zuòwèi","vi":"chỗ ngồi"},{"word":"酒店","py":"jiǔdiàn","vi":"khách sạn"},{"word":"有意思","py":"yǒuyìsi","vi":"thú vị, có ý nghĩa"}]', '[{"q":"王小红和同学要去哪里旅行？","options":["上海","北京","海边"],"answer":0,"qVi":"Vương Tiểu Hồng và bạn học đi du lịch ở đâu?"},{"q":"这是她第几次坐飞机？","options":["第二次","第一次","第三次"],"answer":1,"qVi":"Đây là lần thứ mấy cô ấy đi máy bay?"},{"q":"同学为什么让她别怕？","options":["因为飞机很大","因为坐飞机很安全","因为她坐过飞机"],"answer":1,"qVi":"Vì sao bạn học bảo cô ấy đừng sợ?"},{"q":"下午她们去哪里玩儿？","options":["商场","酒店","海边"],"answer":2,"qVi":"Buổi chiều các cô đi chơi ở đâu?"},{"q":"她们在上海待了多长时间？","options":["两天","一个星期","一个月"],"answer":1,"qVi":"Các cô ở Thượng Hải bao lâu?"}]', 'audio/reading/hsk2-reading-1', 218, 69);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk2-reading-2', 'hsk2', 1, '我的周末', 'Cuối tuần của tôi', '[{"zh":"我叫李文，今年上高中。","py":"Wǒ jiào Lǐ Wén, jīnnián shàng gāozhōng.","vi":"Tôi tên là Lý Văn, năm nay học cấp ba.","audio":"sent-1.mp3","durSec":3.05},{"zh":"平时我要上课，很忙。","py":"Píngshí wǒ yào shàngkè, hěn máng.","vi":"Ngày thường tôi phải đi học, rất bận.","audio":"sent-2.mp3","durSec":2.92},{"zh":"所以我很喜欢周末。","py":"Suǒyǐ wǒ hěn xǐhuan zhōumò.","vi":"Vì vậy tôi rất thích ngày cuối tuần.","audio":"sent-3.mp3","durSec":2.73},{"zh":"星期六早上，我九点才起床。","py":"Xīngqīliù zǎoshang, wǒ jiǔ diǎn cái qǐchuáng.","vi":"Sáng thứ bảy, tôi chín giờ mới dậy.","audio":"sent-4.mp3","durSec":3.77},{"zh":"起床以后，我吃点儿面包，喝一杯牛奶。","py":"Qǐchuáng yǐhòu, wǒ chī diǎnr miànbāo, hē yì bēi niúnǎi.","vi":"Dậy xong, tôi ăn chút bánh mì, uống một cốc sữa.","audio":"sent-5.mp3","durSec":4.28},{"zh":"上午我在家写作业。","py":"Shàngwǔ wǒ zài jiā xiě zuòyè.","vi":"Buổi sáng tôi ở nhà làm bài tập.","audio":"sent-6.mp3","durSec":2.77},{"zh":"写完作业，我打网球或者打篮球。","py":"Xiě wán zuòyè, wǒ dǎ wǎngqiú huòzhě dǎ lánqiú.","vi":"Làm xong bài tập, tôi chơi tennis hoặc chơi bóng rổ.","audio":"sent-7.mp3","durSec":4.03},{"zh":"中午，妈妈做了好吃的饭。","py":"Zhōngwǔ, māma zuò le hǎochī de fàn.","vi":"Buổi trưa, mẹ nấu cơm rất ngon.","audio":"sent-8.mp3","durSec":3.03},{"zh":"我们全家一起吃午饭，很开心。","py":"Wǒmen quán jiā yìqǐ chī wǔfàn, hěn kāixīn.","vi":"Cả nhà tôi cùng nhau ăn trưa, rất vui vẻ.","audio":"sent-9.mp3","durSec":3.75},{"zh":"下午，我常常和同学去公园。","py":"Xiàwǔ, wǒ chángcháng hé tóngxué qù gōngyuán.","vi":"Buổi chiều, tôi thường đi công viên với bạn học.","audio":"sent-10.mp3","durSec":3.7},{"zh":"公园里有很多花，还有小河。","py":"Gōngyuán li yǒu hěn duō huā, hái yǒu xiǎo hé.","vi":"Trong công viên có rất nhiều hoa, còn có dòng sông nhỏ.","audio":"sent-11.mp3","durSec":3.58},{"zh":"我们坐在河边，说说学校里的事情。","py":"Wǒmen zuò zài hé biān, shuōshuo xuéxiào li de shìqing.","vi":"Chúng tôi ngồi bên sông, nói chuyện những việc ở trường.","audio":"sent-12.mp3","durSec":4.2},{"zh":"晚上我在家看小说。","py":"Wǎnshang wǒ zài jiā kàn xiǎoshuō.","vi":"Buổi tối tôi ở nhà đọc tiểu thuyết.","audio":"sent-13.mp3","durSec":2.83},{"zh":"我觉得看小说很有意思。","py":"Wǒ juéde kàn xiǎoshuō hěn yǒuyìsi.","vi":"Tôi thấy đọc tiểu thuyết rất thú vị.","audio":"sent-14.mp3","durSec":3.4},{"zh":"星期天，我们全家去看爷爷和奶奶。","py":"Xīngqītiān, wǒmen quán jiā qù kàn yéye hé nǎinai.","vi":"Chủ nhật, cả nhà tôi đi thăm ông và bà.","audio":"sent-15.mp3","durSec":4.1},{"zh":"奶奶给我们做了很多好吃的菜。","py":"Nǎinai gěi wǒmen zuò le hěn duō hǎochī de cài.","vi":"Bà nấu cho chúng tôi rất nhiều món ngon.","audio":"sent-16.mp3","durSec":3.67},{"zh":"她还让我带回去一些鸡蛋。","py":"Tā hái ràng wǒ dài huíqù yìxiē jīdàn.","vi":"Bà còn cho tôi mang về mấy quả trứng gà.","audio":"sent-17.mp3","durSec":3.38},{"zh":"晚上我准备下周的课。","py":"Wǎnshang wǒ zhǔnbèi xià zhōu de kè.","vi":"Buổi tối tôi chuẩn bị bài cho tuần sau.","audio":"sent-18.mp3","durSec":2.92},{"zh":"我的周末虽然很简单，但是很快乐。","py":"Wǒ de zhōumò suīrán hěn jiǎndān, dànshì hěn kuàilè.","vi":"Cuối tuần của tôi tuy rất đơn giản nhưng rất vui.","audio":"sent-19.mp3","durSec":4.25}]', '[{"word":"平时","py":"píngshí","vi":"ngày thường"},{"word":"周末","py":"zhōumò","vi":"cuối tuần"},{"word":"作业","py":"zuòyè","vi":"bài tập"},{"word":"或者","py":"huòzhě","vi":"hoặc"},{"word":"公园","py":"gōngyuán","vi":"công viên"},{"word":"事情","py":"shìqing","vi":"việc, chuyện"},{"word":"小说","py":"xiǎoshuō","vi":"tiểu thuyết"},{"word":"快乐","py":"kuàilè","vi":"vui vẻ, hạnh phúc"}]', '[{"q":"李文是做什么的？","options":["高中生","大学生","老师"],"answer":0,"qVi":"Lý Văn làm nghề gì?"},{"q":"星期六早上他几点起床？","options":["六点","九点","八点"],"answer":1,"qVi":"Sáng thứ bảy cậu ấy mấy giờ dậy?"},{"q":"写完作业以后他做什么？","options":["看电视","打球","看小说"],"answer":1,"qVi":"Làm bài tập xong cậu ấy làm gì?"},{"q":"星期天全家去看谁？","options":["爷爷和奶奶","外公和外婆","舅舅"],"answer":0,"qVi":"Chủ nhật cả nhà đi thăm ai?"},{"q":"奶奶让李文带什么回去？","options":["一些菜","一些水果","一些鸡蛋"],"answer":2,"qVi":"Bà bảo Lý Văn mang gì về?"}]', 'audio/reading/hsk2-reading-2', 209, 66);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk2-reading-3', 'hsk2', 2, '生病的一天', 'Ngày bị bệnh', '[{"zh":"上周三的早上，我觉得不舒服。","py":"Shàng zhōusān de zǎoshang, wǒ juéde bù shūfu.","vi":"Sáng thứ tư tuần trước, tôi thấy không khỏe.","audio":"sent-1.mp3","durSec":3.83},{"zh":"我的头很疼，也很难受。","py":"Wǒ de tóu hěn téng, yě hěn nánshòu.","vi":"Đầu tôi rất đau, cũng rất khó chịu.","audio":"sent-2.mp3","durSec":3.23},{"zh":"妈妈说：\"你生病了，今天别去学校了。\"","py":"Māma shuō: \"Nǐ shēngbìng le, jīntiān bié qù xuéxiào le.\"","vi":"Mẹ nói: \"Con bị bệnh rồi, hôm nay đừng đi học nữa.\"","audio":"sent-3.mp3","durSec":4.4},{"zh":"妈妈带我去了医院。","py":"Māma dài wǒ qù le yīyuàn.","vi":"Mẹ đưa tôi đến bệnh viện.","audio":"sent-4.mp3","durSec":2.6},{"zh":"医院里人很多，我们先排队。","py":"Yīyuàn li rén hěn duō, wǒmen xiān páiduì.","vi":"Trong bệnh viện rất đông người, chúng tôi xếp hàng trước.","audio":"sent-5.mp3","durSec":3.6},{"zh":"医生问我：\"你哪里不舒服？\"","py":"Yīshēng wèn wǒ: \"Nǐ nǎlǐ bù shūfu?\"","vi":"Bác sĩ hỏi tôi: \"Cậu thấy chỗ nào không khỏe?\"","audio":"sent-6.mp3","durSec":3.23},{"zh":"我说：\"我头疼，还想睡觉。\"","py":"Wǒ shuō: \"Wǒ tóuténg, hái xiǎng shuìjiào.\"","vi":"Tôi nói: \"Con đau đầu, còn buồn ngủ nữa.\"","audio":"sent-7.mp3","durSec":3.33},{"zh":"医生给我检查了一下儿。","py":"Yīshēng gěi wǒ jiǎnchá le yíxiàr.","vi":"Bác sĩ khám cho tôi một chút.","audio":"sent-8.mp3","durSec":2.92},{"zh":"他说：\"吃点儿药就好了，不用怕。\"","py":"Tā shuō: \"Chī diǎnr yào jiù hǎo le, bú yòng pà.\"","vi":"Ông ấy nói: \"Uống chút thuốc là khỏi, đừng lo.\"","audio":"sent-9.mp3","durSec":3.67},{"zh":"妈妈去药店买了药。","py":"Māma qù yàodiàn mǎi le yào.","vi":"Mẹ ra hiệu thuốc mua thuốc.","audio":"sent-10.mp3","durSec":2.67},{"zh":"回家以后，我吃药，然后睡觉。","py":"Huí jiā yǐhòu, wǒ chī yào, ránhòu shuìjiào.","vi":"Về nhà xong, tôi uống thuốc, sau đó đi ngủ.","audio":"sent-11.mp3","durSec":3.6},{"zh":"睡了一觉，我觉得好多了。","py":"Shuì le yí jiào, wǒ juéde hǎo duō le.","vi":"Ngủ một giấc, tôi thấy đỡ nhiều rồi.","audio":"sent-12.mp3","durSec":3.08},{"zh":"妈妈给我做了鸡蛋和面条儿。","py":"Māma gěi wǒ zuò le jīdàn hé miàntiáor.","vi":"Mẹ làm cho tôi trứng và mì.","audio":"sent-13.mp3","durSec":3.4},{"zh":"她说：\"多喝水，很快就好了。\"","py":"Tā shuō: \"Duō hē shuǐ, hěn kuài jiù hǎo le.\"","vi":"Bà ấy nói: \"Uống nhiều nước, sẽ nhanh khỏe thôi.\"","audio":"sent-14.mp3","durSec":3.6},{"zh":"我在家里休息了两天。","py":"Wǒ zài jiā li xiūxi le liǎng tiān.","vi":"Tôi nghỉ ngơi ở nhà hai ngày.","audio":"sent-15.mp3","durSec":2.9},{"zh":"妈妈一直照顾我。","py":"Māma yìzhí zhàogù wǒ.","vi":"Mẹ luôn luôn chăm sóc tôi.","audio":"sent-16.mp3","durSec":2.55},{"zh":"我很感动，也很感谢妈妈。","py":"Wǒ hěn gǎndòng, yě hěn gǎnxiè māma.","vi":"Tôi rất cảm động, cũng rất cảm ơn mẹ.","audio":"sent-17.mp3","durSec":3.35},{"zh":"星期五，我的病好了，又可以去学校了。","py":"Xīngqīwǔ, wǒ de bìng hǎo le, yòu kěyǐ qù xuéxiào le.","vi":"Thứ sáu, bệnh của tôi khỏi rồi, lại có thể đi học được rồi.","audio":"sent-18.mp3","durSec":4.42},{"zh":"同学们看到我，都很高兴。","py":"Tóngxuémen kàndào wǒ, dōu hěn gāoxìng.","vi":"Các bạn học thấy tôi đều rất vui.","audio":"sent-19.mp3","durSec":3.48},{"zh":"从那以后，我明白了：身体健康最重要。","py":"Cóng nà yǐhòu, wǒ míngbái le: shēntǐ jiànkāng zuì zhòngyào.","vi":"Từ đó, tôi hiểu rằng: sức khỏe là quan trọng nhất.","audio":"sent-20.mp3","durSec":4.5}]', '[{"word":"舒服","py":"shūfu","vi":"dễ chịu, khỏe khoắn"},{"word":"头疼","py":"tóuténg","vi":"đau đầu"},{"word":"检查","py":"jiǎnchá","vi":"kiểm tra, khám bệnh"},{"word":"药","py":"yào","vi":"thuốc"},{"word":"照顾","py":"zhàogù","vi":"chăm sóc"},{"word":"感动","py":"gǎndòng","vi":"cảm động"},{"word":"感谢","py":"gǎnxiè","vi":"cảm ơn, biết ơn"},{"word":"健康","py":"jiànkāng","vi":"sức khỏe, khỏe mạnh"}]', '[{"q":"那天早上\"我\"觉得怎么样？","options":["很不舒服","非常高兴","很累但是很好"],"answer":0,"qVi":"Sáng hôm đó \"tôi\" thấy thế nào?"},{"q":"谁带\"我\"去了医院？","options":["爸爸","妈妈","同学"],"answer":1,"qVi":"Ai đưa \"tôi\" đi bệnh viện?"},{"q":"医生说\"我\"应该怎么做？","options":["住院","去学校","吃点儿药"],"answer":2,"qVi":"Bác sĩ nói \"tôi\" nên làm gì?"},{"q":"\"我\"在家里休息了几天？","options":["两天","一个星期","三天"],"answer":0,"qVi":"\"Tôi\" nghỉ ngơi ở nhà mấy ngày?"},{"q":"\"我\"从这件事明白了什么？","options":["学习最重要","身体健康最重要","钱最重要"],"answer":1,"qVi":"Từ chuyện này \"tôi\" hiểu được điều gì?"}]', 'audio/reading/hsk2-reading-3', 212, 68);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk3-reading-1', 'hsk3', 0, '搬家', 'Chuyển nhà', '[{"zh":"上个月我们搬家了，新家在城市的北部。","py":"shàng gè yuè wǒmen bānjiā le, xīn jiā zài chéngshì de běibù.","vi":"Tháng trước chúng tôi chuyển nhà, nhà mới ở phía bắc thành phố.","audio":"sent-1.mp3","durSec":4.53},{"zh":"新家比旧家大，一共有三个房间。","py":"xīn jiā bǐ jiù jiā dà, yīgòng yǒu sān ge fángjiān.","vi":"Nhà mới rộng hơn nhà cũ, tổng cộng có ba phòng.","audio":"sent-2.mp3","durSec":4.15},{"zh":"我的房间朝南，白天非常亮。","py":"wǒ de fángjiān cháo nán, báitiān fēicháng liàng.","vi":"Phòng của tôi quay về hướng nam, ban ngày rất sáng.","audio":"sent-3.mp3","durSec":3.67},{"zh":"妈妈在阳台上放了几盆漂亮的花。","py":"māma zài yángtái shàng fàng le jǐ pén piàoliang de huā.","vi":"Mẹ đặt mấy chậu hoa đẹp trên ban công.","audio":"sent-4.mp3","durSec":4.05},{"zh":"房子旁边有一个超市，买东西很方便。","py":"fángzi pángbiān yǒu yī ge chāoshì, mǎi dōngxi hěn fāngbiàn.","vi":"Cạnh nhà có một siêu thị, mua đồ rất tiện.","audio":"sent-5.mp3","durSec":4.6},{"zh":"爸爸说这里的环境比以前好多了。","py":"bàba shuō zhèlǐ de huánjìng bǐ yǐqián hǎo duō le.","vi":"Bố nói môi trường ở đây tốt hơn trước nhiều.","audio":"sent-6.mp3","durSec":4.12},{"zh":"周末我们请朋友来家里吃饭。","py":"zhōumò wǒmen qǐng péngyou lái jiālǐ chīfàn.","vi":"Cuối tuần chúng tôi mời bạn bè đến nhà ăn cơm.","audio":"sent-7.mp3","durSec":3.7},{"zh":"妈妈做了白菜和鱼，大家都说好吃。","py":"māma zuò le báicài hé yú, dàjiā dōu shuō hǎochī.","vi":"Mẹ làm cải trắng và cá, ai cũng nói ngon.","audio":"sent-8.mp3","durSec":4.28},{"zh":"饭后我帮妈妈洗碗，然后打扫房间。","py":"fàn hòu wǒ bāng māma xǐ wǎn, ránhòu dǎsǎo fángjiān.","vi":"Sau bữa ăn tôi giúp mẹ rửa bát, rồi quét dọn phòng.","audio":"sent-9.mp3","durSec":4.35},{"zh":"弟弟把他的书都放进书柜里。","py":"dìdi bǎ tā de shū dōu fàng jìn shūguì lǐ.","vi":"Em trai xếp hết sách của cậu vào tủ sách.","audio":"sent-10.mp3","durSec":3.77},{"zh":"晚上我们一起看电视，聊了很多。","py":"wǎnshang wǒmen yīqǐ kàn diànshì, liáo le hěnduō.","vi":"Tối đó cả nhà cùng xem tivi, nói chuyện rất nhiều.","audio":"sent-11.mp3","durSec":4.05},{"zh":"朋友走的时候说下个月还要再来。","py":"péngyou zǒu de shíhou shuō xià gè yuè hái yào zài lái.","vi":"Khi về, bạn nói tháng sau còn đến nữa.","audio":"sent-12.mp3","durSec":4.12},{"zh":"我觉得搬新家是件快乐的事。","py":"wǒ juéde bān xīn jiā shì jiàn kuàilè de shì.","vi":"Tôi thấy chuyển nhà mới là một chuyện vui.","audio":"sent-13.mp3","durSec":3.65}]', '[{"word":"搬家","py":"bānjiā","vi":"chuyển nhà"},{"word":"环境","py":"huánjìng","vi":"môi trường"},{"word":"超市","py":"chāoshì","vi":"siêu thị"},{"word":"方便","py":"fāngbiàn","vi":"tiện lợi"},{"word":"房间","py":"fángjiān","vi":"phòng"},{"word":"以前","py":"yǐqián","vi":"trước đây"},{"word":"快乐","py":"kuàilè","vi":"vui vẻ, hạnh phúc"}]', '[{"q":"新家有几个房间？","options":["三个","四个","两个"],"answer":0,"qVi":"Nhà mới có mấy phòng?"},{"q":"为什么在哪儿买东西都很方便？","options":["因为房子旁边有超市","因为爸爸有汽车","因为超市二十四小时开门"],"answer":0,"qVi":"Vì sao mua đồ ở đâu cũng tiện?"},{"q":"饭后\"我\"做了什么？","options":["看了电视","帮妈妈洗碗、打扫房间","去超市买东西"],"answer":1,"qVi":"Sau bữa ăn \"tôi\" đã làm gì?"}]', 'audio/reading/hsk3-reading-1', 174, 53);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk3-reading-2', 'hsk3', 1, '篮球比赛', 'Trận đấu bóng rổ', '[{"zh":"星期六我们班和三班有一场篮球比赛。","py":"xīngqīliù wǒmen bān hé sān bān yǒu yī chǎng lánqiú bǐsài.","vi":"Thứ bảy lớp chúng tôi có một trận bóng rổ với lớp ba.","audio":"sent-1.mp3","durSec":4.62},{"zh":"老师把比赛安排在上午九点。","py":"lǎoshī bǎ bǐsài ānpái zài shàngwǔ jiǔ diǎn.","vi":"Thầy sắp xếp trận đấu vào lúc chín giờ sáng.","audio":"sent-2.mp3","durSec":3.83},{"zh":"比赛的地方是学校的体育馆。","py":"bǐsài de dìfang shì xuéxiào de tǐyùguǎn.","vi":"Nơi thi đấu là nhà thi đấu của trường.","audio":"sent-3.mp3","durSec":3.45},{"zh":"我们每天下午都练习一个小时。","py":"wǒmen měitiān xiàwǔ dōu liànxí yī ge xiǎoshí.","vi":"Chiều nào chúng tôi cũng tập một tiếng.","audio":"sent-4.mp3","durSec":3.8},{"zh":"队长让大家注意传球，不要太着急。","py":"duìzhǎng ràng dàjiā zhùyì chuánqiú, bùyào tài zháojí.","vi":"Đội trưởng bảo mọi người chú ý chuyền bóng, đừng vội vàng.","audio":"sent-5.mp3","durSec":4.33},{"zh":"上半场我们落后了三分，大家有点儿紧张。","py":"shàng bàn chǎng wǒmen luòhòu le sān fēn, dàjiā yǒudiǎnr jǐnzhāng.","vi":"Hiệp một chúng tôi bị dẫn trước ba điểm, mọi người hơi căng thẳng.","audio":"sent-6.mp3","durSec":4.7},{"zh":"中间休息的时候，老师给我们讲了新的办法。","py":"zhōngjiān xiūxi de shíhou, lǎoshī gěi wǒmen jiǎng le xīn de bànfǎ.","vi":"Trong giờ nghỉ, Trong giờ nghỉ, thầy cho chúng tôi biết cách chơi mới.","audio":"sent-7.mp3","durSec":4.83},{"zh":"下半场我们互相配合，慢慢追了回来。","py":"xià bàn chǎng wǒmen hùxiāng pèihé, mànmàn zhuī le huílái.","vi":"Hiệp hai chúng tôi phối hợp với nhau, từ từ đuổi kịp.","audio":"sent-8.mp3","durSec":4.42},{"zh":"最后我们赢了，同学们都非常高兴。","py":"zuìhòu wǒmen yíng le, tóngxuémen dōu fēicháng gāoxìng.","vi":"Cuối cùng chúng tôi thắng, các bạn học sinh đều rất vui.","audio":"sent-9.mp3","durSec":4.33},{"zh":"队长说赢不重要，重要的是大家一起努力。","py":"duìzhǎng shuō yíng bù zhòngyào, zhòngyào de shì dàjiā yīqǐ nǔlì.","vi":"Đội trưởng nói thắng không quan trọng, quan trọng là cùng nhau cố gắng.","audio":"sent-10.mp3","durSec":4.85},{"zh":"晚上我们去吃面条，庆祝这次胜利。","py":"wǎnshang wǒmen qù chī miàntiáo, qìngzhù zhè cì shènglì.","vi":"Tối đó chúng tôi đi ăn mì, ăn mừng chiến thắng lần này.","audio":"sent-11.mp3","durSec":4.2},{"zh":"我觉得这场比赛让我学会了合作。","py":"wǒ juéde zhè chǎng bǐsài ràng wǒ xuéhuì le hézuò.","vi":"Tôi thấy trận đấu này giúp tôi học được cách hợp tác.","audio":"sent-12.mp3","durSec":4.15},{"zh":"下个月还有一场比赛，我们会继续练习。","py":"xià gè yuè hái yǒu yī chǎng bǐsài, wǒmen huì jìxù liànxí.","vi":"Tháng sau còn một trận nữa, chúng tôi sẽ tiếp tục luyện tập.","audio":"sent-13.mp3","durSec":4.62}]', '[{"word":"比赛","py":"bǐsài","vi":"thi đấu, trận đấu"},{"word":"安排","py":"ānpái","vi":"sắp xếp"},{"word":"紧张","py":"jǐnzhāng","vi":"căng thẳng"},{"word":"配合","py":"pèihé","vi":"phối hợp"},{"word":"庆祝","py":"qìngzhù","vi":"chúc mừng, ăn mừng"},{"word":"合作","py":"hézuò","vi":"hợp tác"},{"word":"继续","py":"jìxù","vi":"tiếp tục"}]', '[{"q":"比赛安排在什么时间？","options":["星期六上午九点","星期六下午三点","星期日上午九点"],"answer":0,"qVi":"Trận đấu được sắp xếp vào lúc nào?"},{"q":"上半场我们班怎么样？","options":["赢了三分","落后了三分","和对方一样"],"answer":1,"qVi":"Hiệp một lớp chúng tôi thế nào?"},{"q":"队长认为什么最重要？","options":["赢球","一起努力","多练习传球"],"answer":1,"qVi":"Đội trưởng cho rằng điều gì quan trọng nhất?"}]', 'audio/reading/hsk3-reading-2', 192, 56);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk3-reading-3', 'hsk3', 2, '生病', 'Bị ốm', '[{"zh":"上星期我感冒了，头疼，还一直咳嗽。","py":"shàng xīngqī wǒ gǎnmào le, tóuténg, hái yīzhí késou.","vi":"Tuần trước tôi bị cảm, đau đầu, còn ho mãi không ngừng.","audio":"sent-1.mp3","durSec":4.33},{"zh":"妈妈马上带我去了附近的医院。","py":"māma mǎshàng dài wǒ qù le fùjìn de yīyuàn.","vi":"Mẹ lập tức đưa tôi đến bệnh viện gần đó.","audio":"sent-2.mp3","durSec":3.65},{"zh":"医生问我哪里不舒服，我说嗓子很疼。","py":"yīshēng wèn wǒ nǎlǐ bù shūfu, wǒ shuō sǎngzi hěn téng.","vi":"Bác sĩ hỏi tôi chỗ nào không khỏe, tôi nói họng rất đau.","audio":"sent-3.mp3","durSec":4.45},{"zh":"他给我量了体温，有一点儿高。","py":"tā gěi wǒ liáng le tǐwēn, yǒu yīdiǎnr gāo.","vi":"Ông ấy đo nhiệt độ cho tôi, hơi cao một chút.","audio":"sent-4.mp3","durSec":3.35},{"zh":"医生说不用打针，吃药就可以。","py":"yīshēng shuō bùyòng dǎzhēn, chī yào jiù kěyǐ.","vi":"Bác sĩ nói không cần tiêm, uống thuốc là được.","audio":"sent-5.mp3","durSec":3.88},{"zh":"他让我多喝水，这几天要好好休息。","py":"tā ràng wǒ duō hē shuǐ, zhè jǐ tiān yào hǎohǎo xiūxi.","vi":"Ông ấy dặn tôi uống nhiều nước, mấy ngày này phải nghỉ ngơi cho tốt.","audio":"sent-6.mp3","durSec":4.3},{"zh":"这种药一天吃三次，每次吃两片。","py":"zhè zhǒng yào yī tiān chī sān cì, měi cì chī liǎng piàn.","vi":"Loại thuốc này một ngày uống ba lần, mỗi lần hai viên.","audio":"sent-7.mp3","durSec":4.08},{"zh":"妈妈每天给我做粥，还买来水果。","py":"māma měitiān gěi wǒ zuò zhōu, hái mǎi lái shuǐguǒ.","vi":"Mẹ mỗi ngày nấu cháo cho tôi, còn mua cả trái cây.","audio":"sent-8.mp3","durSec":4.08},{"zh":"我在家休息了三天，没有去上课。","py":"wǒ zài jiā xiūxi le sān tiān, méiyǒu qù shàng kè.","vi":"Tôi nghỉ ở nhà ba ngày, không đi học.","audio":"sent-9.mp3","durSec":4.05},{"zh":"同学们给我发消息，问我的身体怎么样。","py":"tóngxuémen gěi wǒ fā xiāoxi, wèn wǒ de shēntǐ zěnmeyàng.","vi":"Các bạn cùng lớp nhắn tin hỏi thăm sức khỏe của tôi.","audio":"sent-10.mp3","durSec":4.53},{"zh":"星期四我的病好了，又能去上学了。","py":"xīngqīsì wǒ de bìng hǎo le, yòu néng qù shàngxué le.","vi":"Thứ năm bệnh của tôi khỏi, lại có thể đi học được rồi.","audio":"sent-11.mp3","durSec":4.23},{"zh":"医生说春天天气变化大，要小心感冒。","py":"yīshēng shuō chūntiān tiānqì biànhuà dà, yào xiǎoxīn gǎnmào.","vi":"Bác sĩ nói mùa xuân thời tiết thay đổi nhiều, phải cẩn thận tránh cảm.","audio":"sent-12.mp3","durSec":4.62},{"zh":"以后我要多运动，让身体更健康。","py":"yǐhòu wǒ yào duō yùndòng, ràng shēntǐ gèng jiànkāng.","vi":"Sau này tôi sẽ vận động nhiều hơn để cơ thể khỏe mạnh hơn.","audio":"sent-13.mp3","durSec":4.17}]', '[{"word":"感冒","py":"gǎnmào","vi":"bị cảm, cảm lạnh"},{"word":"医生","py":"yīshēng","vi":"bác sĩ"},{"word":"医院","py":"yīyuàn","vi":"bệnh viện"},{"word":"休息","py":"xiūxi","vi":"nghỉ ngơi"},{"word":"变化","py":"biànhuà","vi":"thay đổi"},{"word":"健康","py":"jiànkāng","vi":"khỏe mạnh"},{"word":"运动","py":"yùndòng","vi":"vận động, thể dục"}]', '[{"q":"\"我\"为什么去了医院？","options":["因为头疼、咳嗽","因为要陪妈妈","因为要打针"],"answer":0,"qVi":"Vì sao \"tôi\" đi bệnh viện?"},{"q":"医生说药怎么吃？","options":["一天两次，每次一片","一天三次，每次两片","一天三次，每次一片"],"answer":1,"qVi":"Bác sĩ dặn uống thuốc thế nào?"},{"q":"\"我\"以后打算怎么做？","options":["多喝水","好好休息","多运动"],"answer":2,"qVi":"Sau này \"tôi\" định làm gì?"}]', 'audio/reading/hsk3-reading-3', 177, 54);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk4-reading-1', 'hsk4', 0, '找工作', 'Tìm việc', '[{"zh":"大学毕业以后，我开始认真地找工作。","py":"dàxué bìyè yǐhòu, wǒ kāishǐ rènzhēn de zhǎo gōngzuò.","vi":"Sau khi tốt nghiệp đại học, tôi bắt đầu nghiêm túc tìm việc.","audio":"sent-1.mp3","durSec":4.42},{"zh":"我在网上看到一家公司的招聘信息。","py":"wǒ zài wǎngshàng kàndào yī jiā gōngsī de zhāopìn xìnxī.","vi":"Tôi thấy trên mạng thông tin tuyển dụng của một công ty.","audio":"sent-2.mp3","durSec":4.2},{"zh":"那家公司想招一名翻译，我马上发了简历。","py":"nà jiā gōngsī xiǎng zhāo yī míng fānyì, wǒ mǎshàng fā le jiǎnlì.","vi":"Công ty đó muốn tuyển một phiên dịch, tôi lập tức gửi sơ yếu lý lịch.","audio":"sent-3.mp3","durSec":4.67},{"zh":"星期三上午，我去公司参加了面试。","py":"xīngqīsān shàngwǔ, wǒ qù gōngsī cānjiā le miànshì.","vi":"Sáng thứ tư, tôi đến công ty tham gia phỏng vấn.","audio":"sent-4.mp3","durSec":4.35},{"zh":"面试官先让我做了一个简单的自我介绍。","py":"miànshìguān xiān ràng wǒ zuò le yī ge jiǎndān de zìwǒ jièshào.","vi":"Người phỏng vấn trước tiên cho tôi giới thiệu bản thân ngắn gọn.","audio":"sent-5.mp3","durSec":4.45},{"zh":"我说我大学学的是中文，还做过两年翻译。","py":"wǒ shuō wǒ dàxué xué de shì zhōngwén, hái zuò guo liǎng nián fānyì.","vi":"Tôi nói tôi học tiếng Trung ở đại học, còn làm phiên dịch hai năm.","audio":"sent-6.mp3","durSec":4.9},{"zh":"面试官问我为什么想做这份工作。","py":"miànshìguān wèn wǒ wèishénme xiǎng zuò zhè fèn gōngzuò.","vi":"Người phỏng vấn hỏi tôi vì sao muốn làm công việc này.","audio":"sent-7.mp3","durSec":4.15},{"zh":"我说我一直在努力提高自己的水平。","py":"wǒ shuō wǒ yīzhí zài nǔlì tígāo zìjǐ de shuǐpíng.","vi":"Tôi nói tôi luôn nỗ lực nâng cao trình độ của mình.","audio":"sent-8.mp3","durSec":4.05},{"zh":"他还问，如果顾客不满意，我会怎么办。","py":"tā hái wèn, rúguǒ gùkè bù mǎnyì, wǒ huì zěnme bàn.","vi":"Ông ấy còn hỏi, nếu khách hàng không hài lòng thì tôi sẽ làm sao.","audio":"sent-9.mp3","durSec":4.4},{"zh":"我说我会先听清楚对方的意见，再想办法解决。","py":"wǒ shuō wǒ huì xiān tīng qīngchu duìfāng de yìjiàn, zài xiǎng bànfǎ jiějué.","vi":"Tôi nói tôi sẽ trước tiên lắng nghe rõ ý kiến của đối phương, rồi tìm cách giải quyết.","audio":"sent-10.mp3","durSec":5.2},{"zh":"面试进行了半个小时，气氛还算轻松。","py":"miànshì jìnxíng le bàn ge xiǎoshí, qìfēn hái suàn qīngsōng.","vi":"Cuộc phỏng vấn kéo dài nửa tiếng, không khí khá thoải mái.","audio":"sent-11.mp3","durSec":4.55},{"zh":"两天以后，我收到了被录用的消息。","py":"liǎng tiān yǐhòu, wǒ shōudào le bèi lùyòng de xiāoxi.","vi":"Hai ngày sau, tôi nhận được tin được nhận vào làm.","audio":"sent-12.mp3","durSec":3.83},{"zh":"我把这件事告诉了父母，他们非常高兴。","py":"wǒ bǎ zhè jiàn shì gàosu le fùmǔ, tāmen fēicháng gāoxìng.","vi":"Tôi kể chuyện này cho bố mẹ, họ đều rất vui.","audio":"sent-13.mp3","durSec":4.53},{"zh":"我决定好好干，不放过这次难得的机会。","py":"wǒ juédìng hǎohǎo gàn, bù fàngguò zhè cì nándé de jīhuì.","vi":"Tôi quyết định làm việc thật tốt, không bỏ lỡ cơ hội hiếm có lần này.","audio":"sent-14.mp3","durSec":4.53}]', '[{"word":"毕业","py":"bìyè","vi":"tốt nghiệp"},{"word":"简历","py":"jiǎnlì","vi":"sơ yếu lý lịch"},{"word":"面试","py":"miànshì","vi":"phỏng vấn"},{"word":"翻译","py":"fānyì","vi":"phiên dịch\u003b phiên dịch viên"},{"word":"介绍","py":"jièshào","vi":"giới thiệu"},{"word":"意见","py":"yìjiàn","vi":"ý kiến"},{"word":"决定","py":"juédìng","vi":"quyết định"},{"word":"机会","py":"jīhuì","vi":"cơ hội"}]', '[{"q":"那家公司想招什么人？","options":["翻译","经理","秘书"],"answer":0,"qVi":"Công ty đó muốn tuyển người làm gì?"},{"q":"顾客不满意的时候，\"我\"会先做什么？","options":["找经理帮助","听清楚对方的意见","向顾客道歉"],"answer":1,"qVi":"Khi khách hàng không hài lòng, \"tôi\" sẽ làm gì trước?"},{"q":"\"我\"对这份工作的态度是什么？","options":["先干几天看看","好好干，不放过机会","不太感兴趣"],"answer":1,"qVi":"Thái độ của \"tôi\" đối với công việc này là gì?"}]', 'audio/reading/hsk4-reading-1', 219, 62);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk4-reading-2', 'hsk4', 1, '网上购物', 'Mua sắm trên mạng', '[{"zh":"这几年，网上购物变得越来越普遍。","py":"zhè jǐ nián, wǎngshàng gòuwù biàn de yuèláiyuè pǔbiàn.","vi":"Vài năm gần đây, mua sắm trên mạng ngày càng phổ biến.","audio":"sent-1.mp3","durSec":4.12},{"zh":"人们只要用手机下订单，东西就会送到家里。","py":"rénmen zhǐyào yòng shǒujī xià dìngdān, dōngxi jiù huì sòngdào jiālǐ.","vi":"Người ta chỉ cần đặt hàng bằng điện thoại, đồ sẽ được giao đến nhà.","audio":"sent-2.mp3","durSec":4.97},{"zh":"不管是衣服、食品还是日用品，都能在网上买到。","py":"bùguǎn shì yīfu, shípǐn háishì rìyòngpǐn, dōu néng zài wǎngshàng mǎidào.","vi":"Dù là quần áo, thực phẩm hay đồ dùng hằng ngày, đều có thể mua trên mạng.","audio":"sent-3.mp3","durSec":5.28},{"zh":"我妈妈以前喜欢逛百货商店，现在也常常网上购物。","py":"wǒ māma yǐqián xǐhuan guàng bǎihuò shāngdiàn, xiànzài yě chángcháng wǎngshàng gòuwù.","vi":"Mẹ tôi trước thích đi các cửa hàng bách hóa, giờ cũng thường mua sắm online.","audio":"sent-4.mp3","durSec":5.55},{"zh":"她说网上的东西便宜，还可以比较几家再决定。","py":"tā shuō wǎngshàng de dōngxi piányi, hái kěyǐ bǐjiào jǐ jiā zài juédìng.","vi":"Bà nói đồ trên mạng rẻ, còn có thể so sánh vài nơi rồi mới quyết định.","audio":"sent-5.mp3","durSec":5.08},{"zh":"不过，网上购物也有一些问题。","py":"búguò, wǎngshàng gòuwù yě yǒu yīxiē wèntí.","vi":"Tuy nhiên, mua sắm online cũng có một số vấn đề.","audio":"sent-6.mp3","durSec":3.67},{"zh":"有时候收到的货物和照片上的不一样。","py":"yǒushíhou shōudào de huòwù hé zhàopiàn shàng de bù yīyàng.","vi":"Đôi khi hàng nhận được khác với hình trong ảnh.","audio":"sent-7.mp3","durSec":4.38},{"zh":"遇到这种情况，买家可以联系商家退货。","py":"yùdào zhè zhǒng qíngkuàng, mǎijiā kěyǐ liánxì shāngjiā tuìhuò.","vi":"Gặp trường hợp này, người mua có thể liên hệ người bán để trả lại hàng.","audio":"sent-8.mp3","durSec":4.72},{"zh":"另外，快递太多也会造成污染。","py":"lìngwài, kuàidì tài duō yě huì zàochéng wūrǎn.","vi":"Ngoài ra, quá nhiều bưu kiện cũng gây ra ô nhiễm.","audio":"sent-9.mp3","durSec":3.77},{"zh":"很多人建议少用塑料袋，一起保护环境。","py":"hěn duō rén jiànyì shǎo yòng sùliàodài, yīqǐ bǎohù huánjìng.","vi":"Nhiều người khuyên ít dùng túi ni lông, cùng nhau bảo vệ môi trường.","audio":"sent-10.mp3","durSec":4.62},{"zh":"我觉得网上购物确实方便，但不能乱花钱。","py":"wǒ juéde wǎngshàng gòuwù quèshí fāngbiàn, dàn bùnéng luàn huā qián.","vi":"Tôi thấy mua sắm online quả thật tiện, nhưng không được tiêu tiền tùy tiện.","audio":"sent-11.mp3","durSec":4.9},{"zh":"买东西之前，最好先看看别人的评价。","py":"mǎi dōngxi zhīqián, zuìhǎo xiān kànkan biérén de píngjià.","vi":"Trước khi mua đồ, tốt nhất nên xem đánh giá của người khác.","audio":"sent-12.mp3","durSec":4.45},{"zh":"合理消费，我们的生活才会更好。","py":"hélǐ xiāofèi, wǒmen de shēnghuó cái huì gèng hǎo.","vi":"Tiêu dùng hợp lý, cuộc sống của chúng ta mới tốt hơn.","audio":"sent-13.mp3","durSec":3.9}]', '[{"word":"普遍","py":"pǔbiàn","vi":"phổ biến"},{"word":"百货","py":"bǎihuò","vi":"hàng bách hóa"},{"word":"比较","py":"bǐjiào","vi":"so sánh\u003b khá, tương đối"},{"word":"网络","py":"wǎngluò","vi":"mạng, mạng internet"},{"word":"保护","py":"bǎohù","vi":"bảo vệ"},{"word":"建议","py":"jiànyì","vi":"đề nghị, khuyên"},{"word":"评价","py":"píngjià","vi":"đánh giá"},{"word":"消费","py":"xiāofèi","vi":"tiêu dùng, tiêu phí"}]', '[{"q":"妈妈为什么也常常网上购物？","options":["因为商店太远","因为网上东西便宜，还能比较","因为网上没有假货"],"answer":1,"qVi":"Vì sao mẹ tôi cũng thường mua sắm trên mạng?"},{"q":"收到和照片不一样的货物怎么办？","options":["只能自己用","联系商家退货","在网上骂商家"],"answer":1,"qVi":"Nhận được hàng khác với hình trong ảnh thì phải làm sao?"},{"q":"作者认为网上购物应该注意什么？","options":["不能乱花钱","只买贵的","每天都买东西"],"answer":0,"qVi":"Theo tác giả, mua sắm trên mạng nên chú ý điều gì?"}]', 'audio/reading/hsk4-reading-2', 208, 59);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk4-reading-3', 'hsk4', 2, '团队合作', 'Hợp tác trong nhóm', '[{"zh":"今年我在公司负责一个新的项目。","py":"jīnnián wǒ zài gōngsī fùzé yī ge xīn de xiàngmù.","vi":"Năm nay tôi phụ trách một dự án mới ở công ty.","audio":"sent-1.mp3","durSec":3.98},{"zh":"这个项目时间紧，任务重，需要五个人一起做。","py":"zhè ge xiàngmù shíjiān jǐn, rènwu zhòng, xūyào wǔ ge rén yīqǐ zuò.","vi":"Dự án này thời gian gấp, nhiệm vụ nặng, cần năm người cùng làm.","audio":"sent-2.mp3","durSec":4.92},{"zh":"刚开始的时候，大家的意见不太一样。","py":"gāng kāishǐ de shíhou, dàjiā de yìjiàn bù tài yīyàng.","vi":"Lúc mới bắt đầu, ý kiến của mọi người không thống nhất.","audio":"sent-3.mp3","durSec":4.3},{"zh":"有人觉得应该先做调查，有人想直接开始设计。","py":"yǒu rén juéde yīnggāi xiān zuò diàochá, yǒu rén xiǎng zhíjiē kāishǐ shèjì.","vi":"Người thì cho rằng nên khảo sát trước, người thì muốn thiết kế luôn.","audio":"sent-4.mp3","durSec":5.4},{"zh":"我们开了三次会，最后决定先了解客户的需要。","py":"wǒmen kāi le sān cì huì, zuìhòu juédìng xiān liǎojiě kèhù de xūyào.","vi":"Chúng tôi họp ba lần, cuối cùng quyết định tìm hiểu nhu cầu của khách hàng trước.","audio":"sent-5.mp3","durSec":5.15},{"zh":"团队里的每个人工作都很努力。","py":"tuánduì lǐ de měi ge rén gōngzuò dōu hěn nǔlì.","vi":"Mỗi người trong nhóm đều làm việc rất nỗ lực.","audio":"sent-6.mp3","durSec":3.83},{"zh":"遇到困难的时候，我们互相帮助，互相鼓励。","py":"yùdào kùnnán de shíhou, wǒmen hùxiāng bāngzhù, hùxiāng gǔlì.","vi":"Khi gặp khó khăn, chúng tôi giúp đỡ và động viên lẫn nhau.","audio":"sent-7.mp3","durSec":4.78},{"zh":"小王负责写报告，小李负责联系客户。","py":"xiǎo wáng fùzé xiě bàogào, xiǎo lǐ fùzé liánxì kèhù.","vi":"Tiểu Vương phụ trách viết báo cáo, Tiểu Lý phụ trách liên hệ khách hàng.","audio":"sent-8.mp3","durSec":4.67},{"zh":"我每天记录工作的进度，发现问题马上解决。","py":"wǒ měitiān jìlù gōngzuò de jìndù, fāxiàn wèntí mǎshàng jiějué.","vi":"Tôi mỗi ngày ghi lại tiến độ công việc, phát hiện vấn đề thì giải quyết ngay.","audio":"sent-9.mp3","durSec":5.03},{"zh":"有一次客户突然改变要求，大家只好重新做。","py":"yǒu yī cì kèhù tūrán gǎibiàn yāoqiú, dàjiā zhǐhǎo chóngxīn zuò.","vi":"Có lần khách hàng đột nhiên thay đổi yêu cầu, cả nhóm đành phải làm lại.","audio":"sent-10.mp3","durSec":5.22},{"zh":"虽然辛苦，但是没有人抱怨，也没有人放弃。","py":"suīrán xīnkǔ, dànshì méiyǒu rén bào yuàn, yě méiyǒu rén fàngqì.","vi":"Tuy vất vả, nhưng không ai than phiền, cũng không ai bỏ cuộc.","audio":"sent-11.mp3","durSec":4.58},{"zh":"三个星期以后，我们按时完成了项目。","py":"sān ge xīngqī yǐhòu, wǒmen ànshí wánchéng le xiàngmù.","vi":"Ba tuần sau, chúng tôi hoàn thành dự án đúng thời hạn.","audio":"sent-12.mp3","durSec":4.28},{"zh":"客户对结果非常满意，还说要和我们长期合作。","py":"kèhù duì jiéguǒ fēicháng mǎnyì, hái shuō yào hé wǒmen chángqī hézuò.","vi":"Khách hàng rất hài lòng với kết quả, còn nói muốn hợp tác lâu dài với chúng tôi.","audio":"sent-13.mp3","durSec":5.3},{"zh":"这件事让我明白，成功离不开团队的合作。","py":"zhè jiàn shì ràng wǒ míngbai, chénggōng líbùkāi tuánduì de hézuò.","vi":"Chuyện này khiến tôi hiểu rằng, thành công không thể thiếu sự hợp tác của cả nhóm.","audio":"sent-14.mp3","durSec":4.75}]', '[{"word":"项目","py":"xiàngmù","vi":"dự án"},{"word":"负责","py":"fùzé","vi":"phụ trách, chịu trách nhiệm"},{"word":"调查","py":"diàochá","vi":"điều tra, khảo sát"},{"word":"报告","py":"bàogào","vi":"báo cáo"},{"word":"记录","py":"jìlù","vi":"ghi chép, ghi lại"},{"word":"按时","py":"ànshí","vi":"đúng giờ, đúng hạn"},{"word":"满意","py":"mǎnyì","vi":"hài lòng"},{"word":"合作","py":"hézuò","vi":"hợp tác"}]', '[{"q":"团队最后决定先做什么？","options":["直接开始设计","了解客户的需要","开五次会"],"answer":1,"qVi":"Cuối cùng nhóm quyết định làm gì trước?"},{"q":"客户突然改变要求以后，大家怎么样？","options":["有人放弃了","抱怨了很多","只好重新做"],"answer":2,"qVi":"Sau khi khách hàng đột nhiên thay đổi yêu cầu, mọi người thế nào?"},{"q":"作者从这件事中明白了什么？","options":["成功离不开合作","开会没有用","工作很辛苦"],"answer":0,"qVi":"Tác giả hiểu được điều gì từ chuyện này?"}]', 'audio/reading/hsk4-reading-3', 234, 66);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk5-reading-1', 'hsk5', 0, '茶文化', 'Văn hóa trà', '[{"zh":"中国人喝茶已经有几千年的历史了。","py":"zhōngguó rén hē chá yǐjīng yǒu jǐ qiān nián de lìshǐ le.","vi":"Người Trung Quốc uống trà đã có lịch sử vài nghìn năm.","audio":"sent-1.mp3","durSec":4.35},{"zh":"对中国人来说，茶不仅仅是一种饮料，更是一种文化。","py":"duì zhōngguó rén lái shuō, chá bùjǐnjǐn shì yī zhǒng yǐnliào, gèng shì yī zhǒng wénhuà.","vi":"Đối với người Trung Quốc, trà không chỉ là một loại thức uống, mà còn là một nền văn hóa.","audio":"sent-2.mp3","durSec":5.58},{"zh":"传统的中国茶分为绿茶、红茶、乌龙茶等很多种类。","py":"chuántǒng de zhōngguó chá fēn wéi lǜchá, hóngchá, wūlóngchá děng hěn duō zhǒnglèi.","vi":"Trà Trung Quốc truyền thống chia thành trà xanh, trà đỏ, trà ô long v.v. nhiều loại.","audio":"sent-3.mp3","durSec":5.8},{"zh":"不同地区出产的茶叶，味道和香气也各不相同。","py":"bùtóng dìqū chūchǎn de cháyè, wèidào hé xiāngqì yě gè bù xiāngtóng.","vi":"Trà sản xuất ở các vùng khác nhau, hương vị cũng khác nhau.","audio":"sent-4.mp3","durSec":5.3},{"zh":"南方人喜欢喝绿茶，非常讲究茶叶的新鲜。","py":"nánfāng rén xǐhuan hē lǜchá, fēicháng jiǎngjiu cháyè de xīnxiān.","vi":"Người miền nam thích uống trà xanh, rất chú trọng độ tươi của trà.","audio":"sent-5.mp3","durSec":4.9},{"zh":"北方人则更喜欢香味浓的花茶。","py":"běifāng rén zé gèng xǐhuan xiāngwèi nóng de huāchá.","vi":"Người miền bắc lại thích trà hoa có hương đậm hơn.","audio":"sent-6.mp3","durSec":4.03},{"zh":"泡茶也是一门学问，水温和时间都会影响茶的味道。","py":"pào chá yě shì yī mén xuéwen, shuǐwēn hé shíjiān dōu huì yǐngxiǎng chá de wèidào.","vi":"Pha trà cũng là một môn học, nhiệt độ nước và thời gian đều ảnh hưởng đến vị trà.","audio":"sent-7.mp3","durSec":5.6},{"zh":"老年人常说，喝茶可以让人安静下来。","py":"lǎonián rén cháng shuō, hē chá kěyǐ ràng rén ānjìng xiàlái.","vi":"Người già thường nói, uống trà có thể khiến người ta bình tĩnh lại.","audio":"sent-8.mp3","durSec":4.33},{"zh":"现在，越来越多的年轻人对茶文化产生了兴趣。","py":"xiànzài, yuèláiyuè duō de niánqīng rén duì chá wénhuà chǎnshēng le xìngqù.","vi":"Hiện nay, ngày càng nhiều bạn trẻ có hứng thú với văn hóa trà.","audio":"sent-9.mp3","durSec":5.17},{"zh":"城市里出现了不少有特色的茶馆，生意相当不错。","py":"chéngshì lǐ chūxiàn le bù shǎo yǒu tèsè de cháguǎn, shēngyì xiāngdāng bùcuò.","vi":"Ở thành phố xuất hiện không ít quán trà có đặc sắc, việc làm ăn khá tốt.","audio":"sent-10.mp3","durSec":5.45},{"zh":"周末约上几位朋友，在茶馆里聊聊天，是一种享受。","py":"zhōumò yuē shàng jǐ wèi péngyou, zài cháguǎn lǐ liáo liáo tiān, shì yī zhǒng xiǎngshòu.","vi":"Cuối tuần hẹn vài người bạn, ngồi trò chuyện trong quán trà, là một sự hưởng thụ.","audio":"sent-11.mp3","durSec":5.53},{"zh":"有人认为，喝咖啡代表现代，喝茶代表传统。","py":"yǒu rén rènwéi, hē kāfēi dàibiǎo xiàndài, hē chá dàibiǎo chuántǒng.","vi":"Có người cho rằng, uống cà phê đại diện cho hiện đại, uống trà đại diện cho truyền thống.","audio":"sent-12.mp3","durSec":4.97},{"zh":"但我觉得，两者完全可以同时存在。","py":"dàn wǒ juéde, liǎng zhě wánquán kěyǐ tóngshí cúnzài.","vi":"Nhưng tôi nghĩ, hai thứ này hoàn toàn có thể cùng tồn tại.","audio":"sent-13.mp3","durSec":4.23},{"zh":"传统的文化只有融进现代生活，才能真正流传下去。","py":"chuántǒng de wénhuà zhǐyǒu róng jìn xiàndài shēnghuó, cái néng zhēnzhèng liúchuán xiàqù.","vi":"Văn hóa truyền thống chỉ có hòa vào cuộc sống hiện đại, mới có thể thực sự được lưu truyền.","audio":"sent-14.mp3","durSec":5.72}]', '[{"word":"传统","py":"chuántǒng","vi":"truyền thống"},{"word":"饮料","py":"yǐnliào","vi":"thức uống"},{"word":"讲究","py":"jiǎngjiu","vi":"chú trọng, cầu kỳ"},{"word":"学问","py":"xuéwen","vi":"học vấn, kiến thức"},{"word":"兴趣","py":"xìngqù","vi":"hứng thú, sở thích"},{"word":"特色","py":"tèsè","vi":"đặc sắc"},{"word":"享受","py":"xiǎngshòu","vi":"hưởng thụ"},{"word":"流传","py":"liúchuán","vi":"lưu truyền"}]', '[{"q":"对中国人来说，茶是什么？","options":["只是一种饮料","一种饮料，也是一种文化","一种药"],"answer":1,"qVi":"Đối với người Trung Quốc, trà là gì?"},{"q":"北方人更喜欢什么茶？","options":["香味浓的花茶","新鲜的绿茶","苦的红茶"],"answer":0,"qVi":"Người miền bắc thích loại trà nào hơn?"},{"q":"作者认为传统文化怎样才能流传下去？","options":["靠老年人保护","不和现代生活混合","融进现代生活"],"answer":2,"qVi":"Theo tác giả, văn hóa truyền thống phải thế nào mới được lưu truyền?"}]', 'audio/reading/hsk5-reading-1', 252, 71);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk5-reading-2', 'hsk5', 1, '谈谈读书', 'Nói về việc đọc sách', '[{"zh":"现在很多人习惯用手机看新闻、看小说，读书的人似乎越来越少。","py":"xiànzài hěn duō rén xíguàn yòng shǒujī kàn xīnwén, kàn xiǎoshuō, dú shū de rén sìhū yuèláiyuè shǎo.","vi":"Hiện nay nhiều người quen dùng điện thoại xem tin tức, xem tiểu thuyết, người đọc sách có vẻ ngày càng ít.","audio":"sent-1.mp3","durSec":6.7},{"zh":"有人说，纸质书早晚会被电子书代替。","py":"yǒu rén shuō, zhǐzhì shū zǎowǎn huì bèi diànzǐshū dàitì.","vi":"Có người nói, sách giấy sớm muộn sẽ bị sách điện tử thay thế.","audio":"sent-2.mp3","durSec":4.4},{"zh":"但我认为，两种阅读方式各有优点，谁也代替不了谁。","py":"dàn wǒ rènwéi, liǎng zhǒng yuèdú fāngshì gè yǒu yōudiǎn, shéi yě dàitì bù liǎo shéi.","vi":"Nhưng tôi cho rằng, hai cách đọc này mỗi cái có ưu điểm riêng, cái nào cũng không thay thế được cái nào.","audio":"sent-3.mp3","durSec":5.5},{"zh":"电子书方便携带，价格也往往更便宜。","py":"diànzǐshū fāngbiàn xiédài, jiàgé yě wǎngwǎng gèng piányi.","vi":"Sách điện tử tiện mang theo, giá cũng thường rẻ hơn.","audio":"sent-4.mp3","durSec":4.53},{"zh":"而读纸质书更容易让人静下心来，体验也更深刻。","py":"ér dú zhǐzhì shū gèng róngyì ràng rén jìng xià xīn lái, tǐyàn yě gèng shēnkè.","vi":"Còn đọc sách giấy dễ khiến người ta tĩnh tâm hơn, trải nghiệm cũng sâu sắc hơn.","audio":"sent-5.mp3","durSec":5.38},{"zh":"我认识一位老教授，他家里收藏了几千本书。","py":"wǒ rènshi yī wèi lǎo jiàoshòu, tā jiā lǐ shōucáng le jǐ qiān běn shū.","vi":"Tôi quen một giáo sư già, nhà ông ấy sưu tầm vài nghìn cuốn sách.","audio":"sent-6.mp3","durSec":4.9},{"zh":"他说，读书不能只为了考试，更是为了思考。","py":"tā shuō, dú shū bù néng zhǐ wèile kǎoshì, gèng shì wèile sīkǎo.","vi":"Ông nói, đọc sách không thể chỉ vì thi cử, mà quan trọng hơn là để tư duy.","audio":"sent-7.mp3","durSec":4.7},{"zh":"一本好书就像一位好朋友，会影响你一辈子。","py":"yī běn hǎo shū jiù xiàng yī wèi hǎo péngyou, huì yǐngxiǎng nǐ yībèizi.","vi":"Một cuốn sách hay giống như một người bạn tốt, sẽ ảnh hưởng đến bạn cả đời.","audio":"sent-8.mp3","durSec":4.85},{"zh":"当然，读什么书也很重要，要选择对自己有帮助的。","py":"dāngrán, dú shénme shū yě hěn zhòngyào, yào xuǎnzé duì zìjǐ yǒu bāngzhù de.","vi":"Tất nhiên, đọc sách gì cũng rất quan trọng, phải chọn sách có lợi cho mình.","audio":"sent-9.mp3","durSec":5.28},{"zh":"现在不少城市开设了二十四小时图书馆，鼓励市民多读书。","py":"xiànzài bù shǎo chéngshì kāishè le èrshísì xiǎoshí túshūguǎn, gǔlì shìmín duō dú shū.","vi":"Hiện nay không ít thành phố mở thư viện hai mươi bốn giờ, khuyến khích dân chúng đọc sách nhiều hơn.","audio":"sent-10.mp3","durSec":6.22},{"zh":"图书馆里的气氛，能让人的心态自然而然地安静下来。","py":"túshūguǎn lǐ de qìfēn, néng ràng rén de xīntài zìrán ér rán de ānjìng xiàlái.","vi":"Không khí trong thư viện có thể khiến tâm trạng người ta tự nhiên bình tĩnh lại.","audio":"sent-11.mp3","durSec":5.5},{"zh":"我建议每个星期至少抽出一个小时，关掉手机，认真读点书。","py":"wǒ jiànyì měi ge xīngqī zhìshǎo chōuchū yī ge xiǎoshí, guān diào shǒujī, rènzhēn dú diǎn shū.","vi":"Tôi đề nghị mỗi tuần ít nhất dành ra một tiếng, tắt điện thoại, nghiêm túc đọc chút sách.","audio":"sent-12.mp3","durSec":6.22},{"zh":"长期坚持下来，你会发现自己的视野宽了，想法也成熟了。","py":"chángqī jiānchí xiàlái, nǐ huì fāxiàn zìjǐ de shìyě kuān le, xiǎngfǎ yě chéngshú le.","vi":"Kiên trì lâu dài, bạn sẽ phát hiện tầm nhìn của mình rộng hơn, suy nghĩ cũng chín chắn hơn.","audio":"sent-13.mp3","durSec":5.95},{"zh":"读书是一种习惯，更是一种生活态度。","py":"dú shū shì yī zhǒng xíguàn, gèng shì yī zhǒng shēnghuó tàidù.","vi":"Đọc sách là một thói quen, mà quan trọng hơn là một thái độ sống.","audio":"sent-14.mp3","durSec":4.45}]', '[{"word":"习惯","py":"xíguàn","vi":"thói quen\u003b quen"},{"word":"代替","py":"dàitì","vi":"thay thế"},{"word":"优点","py":"yōudiǎn","vi":"ưu điểm"},{"word":"体验","py":"tǐyàn","vi":"trải nghiệm"},{"word":"深刻","py":"shēnkè","vi":"sâu sắc"},{"word":"图书馆","py":"túshūguǎn","vi":"thư viện"},{"word":"坚持","py":"jiānchí","vi":"kiên trì"},{"word":"态度","py":"tàidù","vi":"thái độ"}]', '[{"q":"作者怎样看电子书和纸质书？","options":["电子书会完全代替纸质书","两种方式各有优点","纸质书没有优点"],"answer":1,"qVi":"Tác giả nhìn nhận sách điện tử và sách giấy thế nào?"},{"q":"老教授认为读书是为了什么？","options":["只为了考试","为了思考","为了收藏书"],"answer":1,"qVi":"Giáo sư già cho rằng đọc sách là để làm gì?"},{"q":"作者建议大家每星期做什么？","options":["买一本书","去一次图书馆","抽一个小时认真读书"],"answer":2,"qVi":"Tác giả khuyên mỗi tuần nên làm gì?"}]', 'audio/reading/hsk5-reading-2', 278, 75);
INSERT OR REPLACE INTO content_readings (id, level, ord, title, title_vi, sentences, vocab, questions, audio_dir, chars, duration_sec) VALUES ('hsk5-reading-3', 'hsk5', 2, '春节', 'Tết Nguyên Đán', '[{"zh":"春节是中国最重要的传统节日。","py":"chūnjié shì zhōngguó zuì zhòngyào de chuántǒng jiérì.","vi":"Tết Nguyên Đán là ngày lễ truyền thống quan trọng nhất của Trung Quốc.","audio":"sent-1.mp3","durSec":4},{"zh":"每年春节前，家家户户都忙着买年货、打扫房子。","py":"měi nián chūnjié qián, jiājiāhùhù dōu mángzhe mǎi niánhuò, dǎsǎo fángzi.","vi":"Mỗi năm trước Tết, nhà nào cũng bận rộn mua đồ Tết, dọn dẹp nhà cửa.","audio":"sent-2.mp3","durSec":5.58},{"zh":"在外地工作的人也纷纷赶回家，和家人团聚。","py":"zài wàidì gōngzuò de rén yě fēnfēn gǎn huí jiā, hé jiārén tuánjù.","vi":"Những người làm việc ở xa cũng nối nhau vội về nhà, đoàn tụ với gia đình.","audio":"sent-3.mp3","durSec":5.17},{"zh":"除夕那天晚上，全家人一起吃年夜饭，气氛特别热闹。","py":"chúxī nà tiān wǎnshang, quán jiā rén yīqǐ chī niányèfàn, qìfēn tèbié rènao.","vi":"Tối giao thừa, cả gia đình cùng ăn bữa cơm tất niên, không khí đặc biệt náo nhiệt.","audio":"sent-4.mp3","durSec":5.78},{"zh":"北方人习惯吃饺子，南方人则常吃年糕。","py":"běifāng rén xíguàn chī jiǎozi, nánfāng rén zé cháng chī niángāo.","vi":"Người miền bắc quen ăn sủi cảo, người miền nam thường ăn bánh chưng năm.","audio":"sent-5.mp3","durSec":4.9},{"zh":"吃完饭，大家一边看节目，一边聊天，一直到半夜。","py":"chī wán fàn, dàjiā yībiān kàn jiémù, yībiān liáotiān, yīzhí dào bànyè.","vi":"Ăn cơm xong, mọi người vừa xem chương trình vừa nói chuyện, cho đến nửa đêm.","audio":"sent-6.mp3","durSec":5.22},{"zh":"大年初一，孩子们给长辈拜年，还能收到红包。","py":"dà nián chūyī, háizimen gěi zhǎngbèi bàinián, hái néng shōudào hóngbāo.","vi":"Mùng một Tết, các cháu chúc Tết người lớn, còn nhận được bao lì xì.","audio":"sent-7.mp3","durSec":5},{"zh":"很多地方还会放鞭炮，据说这样可以赶走坏运气。","py":"hěn duō dìfang hái huì fàng biānpào, jùshuō zhèyàng kěyǐ gǎnzǒu huài yùnqì.","vi":"Nhiều nơi còn đốt pháo, theo như lời kể thì làm vậy có thể xua đuổi vận xui.","audio":"sent-8.mp3","durSec":5.45},{"zh":"近年来，为了保护环境，不少城市禁止放鞭炮。","py":"jìnnián lái, wèile bǎohù huánjìng, bù shǎo chéngshì jìnzhǐ fàng biānpào.","vi":"Những năm gần đây, để bảo vệ môi trường, không ít thành phố cấm đốt pháo.","audio":"sent-9.mp3","durSec":5.12},{"zh":"有些人觉得这样少了节日气氛，有些人则表示理解。","py":"yǒuxiē rén juéde zhèyàng shǎo le jiérì qìfēn, yǒuxiē rén zé biǎoshì lǐjiě.","vi":"Có người thấy vậy làm mất bớt không khí lễ hội, có người lại tỏ ra thông cảm.","audio":"sent-10.mp3","durSec":5.58},{"zh":"我认为，节日的核心是亲情，形式可以慢慢变化。","py":"wǒ rènwéi, jiérì de héxīn shì qīnqíng, xíngshì kěyǐ mànmàn biànhuà.","vi":"Tôi cho rằng, cốt lõi của lễ Tết là tình thân, hình thức có thể dần thay đổi.","audio":"sent-11.mp3","durSec":5.22},{"zh":"比如现在流行用手机发红包、视频拜年，同样能表达心意。","py":"bǐrú xiànzài liúxíng yòng shǒujī fā hóngbāo, shìpín bàinián, tóngyàng néng biǎodá xīnyì.","vi":"Chẳng hạn nay thịnh hành gửi lì xì bằng điện thoại, chúc Tết qua video, vẫn thể hiện được tấm lòng.","audio":"sent-12.mp3","durSec":6.22},{"zh":"春节让人们暂时放下工作，回到家庭，这本身就是它的意义。","py":"chūnjié ràng rénmen zànshí fàngxià gōngzuò, huídào jiātíng, zhè běnshēn jiù shì tā de yìyì.","vi":"Tết khiến mọi người tạm thời gác lại công việc, trở về với gia đình, điều đó tự nó đã là ý nghĩa của Tết.","audio":"sent-13.mp3","durSec":6.3},{"zh":"无论时代怎么变，团圆永远是中国人心里最深的感情。","py":"wúlùn shídài zěnme biàn, tuányuán yǒngyuǎn shì zhōngguó rén xīnlǐ zuì shēn de gǎnqíng.","vi":"Dù thời đại thay đổi thế nào, đoàn viên mãi mãi là tình cảm sâu nhất trong lòng người Trung Quốc.","audio":"sent-14.mp3","durSec":5.58}]', '[{"word":"节日","py":"jiérì","vi":"ngày lễ, ngày hội"},{"word":"热闹","py":"rènao","vi":"náo nhiệt"},{"word":"饺子","py":"jiǎozi","vi":"sủi cảo, bánh chẻo"},{"word":"红包","py":"hóngbāo","vi":"bao lì xì"},{"word":"禁止","py":"jìnzhǐ","vi":"cấm chỉ, cấm"},{"word":"意义","py":"yìyì","vi":"ý nghĩa"},{"word":"表达","py":"biǎodá","vi":"biểu đạt, bày tỏ"},{"word":"感情","py":"gǎnqíng","vi":"tình cảm"}]', '[{"q":"为什么不少城市禁止放鞭炮？","options":["因为鞭炮太贵","为了保护环境","因为大家不喜欢"],"answer":1,"qVi":"Vì sao không ít thành phố cấm đốt pháo?"},{"q":"作者认为节日的核心是什么？","options":["吃年夜饭","收红包","亲情"],"answer":2,"qVi":"Tác giả cho rằng cốt lõi của ngày lễ là gì?"},{"q":"用手机发红包、视频拜年能表达心意吗？","options":["作者认为同样能","完全不能","文章没有提到"],"answer":0,"qVi":"Gửi lì xì bằng điện thoại, chúc Tết qua video có thể thể hiện tấm lòng không?"}]', 'audio/reading/hsk5-reading-3', 271, 75);
